using System;
using Framework.Grid;
using Framework.Pathfinding;
using UnityEngine;

namespace Framework.AI.Perception
{
    /// <summary>
    /// グリッド上の仮想音源を認識する聴覚センサー。
    /// </summary>
    /// <typeparam name="T">グリッドのセルデータ型</typeparam>
    /// <remarks>
    /// 音源までの通路距離を利用して認識判定を行う。
    /// 実際のオーディオ再生には依存しない。
    /// </remarks>
    public sealed class GridHearingSensor<T> : IDisposable
    {
        /// <summary>
        /// 音の伝播距離を管理する距離マップ。
        /// </summary>
        private readonly GridDistanceMap<T> distanceMap;

        /// <summary>
        /// 音が通過可能なセルを判定する処理。
        /// </summary>
        private readonly Func<Vector2Int, bool> canTransmitSound;

        /// <summary>
        /// 距離マップの再計算が必要であるか。
        /// </summary>
        private bool isDirty = true;

        /// <summary>
        /// 対象のグリッドマップ。
        /// </summary>
        public GridMap<T> Map { get; }

        /// <summary>
        /// 基準聴覚範囲。単位はセル。
        /// </summary>
        public float Range { get; private set; }

        /// <summary>
        /// 聴覚感度。範囲は0から1。
        /// </summary>
        public float Sensitivity { get; private set; }

        /// <summary>
        /// 聴覚センサーが有効であるか。
        /// </summary>
        public bool IsEnabled =>
            !IsDisposed && Range > 0f;

        /// <summary>
        /// 距離マップの再計算回数。
        /// </summary>
        public long RecalculationCount { get; private set; }

        /// <summary>
        /// 解放済みであるか。
        /// </summary>
        public bool IsDisposed { get; private set; }

        /// <summary>
        /// 聴覚センサーを生成する。
        /// </summary>
        /// <param name="map">対象マップ</param>
        /// <param name="canTransmitSound">音の通過判定</param>
        /// <param name="range">基準聴覚範囲</param>
        /// <param name="sensitivity">聴覚感度</param>
        public GridHearingSensor(
            GridMap<T> map,
            Func<Vector2Int, bool> canTransmitSound,
            float range = 8f,
            float sensitivity = 0.5f)
        {
            Map = map ??
                throw new ArgumentNullException(nameof(map));

            this.canTransmitSound = canTransmitSound ??
                throw new ArgumentNullException(
                    nameof(canTransmitSound));

            Configure(range, sensitivity);

            distanceMap = new GridDistanceMap<T>(
                Map,
                this.canTransmitSound);

            Map.CellChanged += HandleCellChanged;
        }

        /// <summary>
        /// 聴覚能力を設定する。
        /// </summary>
        /// <param name="newRange">基準聴覚範囲</param>
        /// <param name="newSensitivity">聴覚感度</param>
        public void Configure(
            float newRange,
            float newSensitivity)
        {
            if (IsDisposed)
            {
                throw new ObjectDisposedException(
                    nameof(GridHearingSensor<T>));
            }

            if (float.IsNaN(newRange) ||
                float.IsInfinity(newRange) ||
                newRange < 0f)
            {
                throw new ArgumentOutOfRangeException(
                    nameof(newRange));
            }

            if (float.IsNaN(newSensitivity) ||
                float.IsInfinity(newSensitivity) ||
                newSensitivity < 0f ||
                newSensitivity > 1f)
            {
                throw new ArgumentOutOfRangeException(
                    nameof(newSensitivity));
            }

            Range = newRange;
            Sensitivity = newSensitivity;
        }

        /// <summary>
        /// 音量に応じた実効聴覚範囲を取得する。
        /// </summary>
        /// <param name="volume">音量。範囲は0から1</param>
        /// <returns>実効聴覚範囲</returns>
        public float GetEffectiveRange(float volume)
        {
            if (!IsEnabled ||
                !IsValidVolume(volume))
            {
                return 0f;
            }

            return Range *
                   volume *
                   (0.5f + Sensitivity);
        }

        /// <summary>
        /// 音源までの通路距離を取得する。
        /// </summary>
        /// <param name="origin">認識者の位置</param>
        /// <param name="source">音源の位置</param>
        /// <returns>通路距離。取得不能時は-1</returns>
        public int GetDistance(
            Vector2Int origin,
            Vector2Int source)
        {
            if (IsDisposed ||
                !Map.IsInside(origin) ||
                !Map.IsInside(source) ||
                !canTransmitSound(origin) ||
                !canTransmitSound(source))
            {
                return -1;
            }

            // 起点または地形が変化した場合のみ再計算する。
            if (isDirty ||
                !distanceMap.IsCalculated ||
                distanceMap.Origin != origin)
            {
                RecalculationCount++;

                if (!distanceMap.Calculate(origin))
                {
                    return -1;
                }

                isDirty = false;
            }

            return distanceMap.GetDistance(source);
        }

        /// <summary>
        /// 音源を認識できるか判定する。
        /// </summary>
        /// <param name="origin">認識者の位置</param>
        /// <param name="source">音源の位置</param>
        /// <param name="volume">音量</param>
        /// <returns>認識可能な場合はtrue</returns>
        public bool CanHear(
            Vector2Int origin,
            Vector2Int source,
            float volume)
        {
            float effectiveRange =
                GetEffectiveRange(volume);

            if (effectiveRange <= 0f)
            {
                return false;
            }

            int distance = GetDistance(
                origin,
                source);

            return distance >= 0 &&
                   distance <= effectiveRange;
        }

        /// <summary>
        /// 音源の認識信頼度を取得する。
        /// </summary>
        /// <param name="origin">認識者の位置</param>
        /// <param name="source">音源の位置</param>
        /// <param name="volume">音量</param>
        /// <returns>認識信頼度。範囲は0から1</returns>
        public float GetConfidence(
            Vector2Int origin,
            Vector2Int source,
            float volume)
        {
            float effectiveRange =
                GetEffectiveRange(volume);

            if (effectiveRange <= 0f)
            {
                return 0f;
            }

            int distance = GetDistance(
                origin,
                source);

            if (distance < 0 ||
                distance > effectiveRange)
            {
                return 0f;
            }

            // 聴覚範囲の境界でも最低限の信頼度を残す。
            float distanceWeight =
                1f - distance / effectiveRange;

            return Mathf.Clamp01(
                0.2f + distanceWeight * 0.8f);
        }

        /// <summary>
        /// 音源から聴覚刺激を生成する。
        /// </summary>
        /// <param name="sourceId">音源の識別子</param>
        /// <param name="origin">認識者の位置</param>
        /// <param name="source">音源の位置</param>
        /// <param name="volume">音量</param>
        /// <param name="timestamp">認識時刻</param>
        /// <param name="stimulus">生成された聴覚刺激</param>
        /// <returns>認識に成功した場合はtrue</returns>
        public bool TryObserve(
            Guid sourceId,
            Vector2Int origin,
            Vector2Int source,
            float volume,
            double timestamp,
            out PerceptionStimulus<Vector2Int> stimulus)
        {
            stimulus = default;

            if (sourceId == Guid.Empty ||
                double.IsNaN(timestamp) ||
                double.IsInfinity(timestamp) ||
                timestamp < 0d)
            {
                return false;
            }

            float confidence = GetConfidence(
                origin,
                source,
                volume);

            if (confidence <= 0f)
            {
                return false;
            }

            stimulus =
                new PerceptionStimulus<Vector2Int>(
                    sourceId,
                    PerceptionType.Hearing,
                    source,
                    confidence,
                    timestamp);

            return true;
        }

        /// <summary>
        /// 音の伝播距離キャッシュを無効化する。
        /// </summary>
        public void Invalidate()
        {
            if (!IsDisposed)
            {
                isDirty = true;
            }
        }

        /// <summary>
        /// マップのセル変更を処理する。
        /// </summary>
        /// <param name="position">変更位置</param>
        /// <param name="previous">変更前の値</param>
        /// <param name="current">変更後の値</param>
        private void HandleCellChanged(
            Vector2Int position,
            T previous,
            T current)
        {
            // 汎用セル型では地形変更とアイテム変更を
            // 区別できないため、保守的に無効化する。
            Invalidate();
        }

        /// <summary>
        /// 音量が有効な値であるか判定する。
        /// </summary>
        /// <param name="volume">音量</param>
        /// <returns>有効な場合はtrue</returns>
        private static bool IsValidVolume(float volume)
        {
            return !float.IsNaN(volume) &&
                   !float.IsInfinity(volume) &&
                   volume >= 0f &&
                   volume <= 1f;
        }

        /// <summary>
        /// 所有する資源とイベント購読を解放する。
        /// </summary>
        public void Dispose()
        {
            if (IsDisposed)
            {
                return;
            }

            Map.CellChanged -= HandleCellChanged;

            distanceMap.Clear();

            IsDisposed = true;
        }
    }
}
